sealed class SshException: kotlin.Exception() {
    
    class Connect(
        
        val `msg`: kotlin.String
        ) : SshException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class HostKeyRejected(
        ) : SshException() {
        override val message
            get() = ""
    }
    
    class PassphraseRequired(
        ) : SshException() {
        override val message
            get() = ""
    }
    
    class BadPassphrase(
        ) : SshException() {
        override val message
            get() = ""
    }
    
    class InvalidKey(
        
        val `msg`: kotlin.String
        ) : SshException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Auth(
        
        val `msg`: kotlin.String
        ) : SshException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * Nothing this login has fits what the server accepts.
     */
    class AuthMethodNotAvailable(
        
        val `msg`: kotlin.String
        ) : SshException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class AuthCancelled(
        ) : SshException() {
        override val message
            get() = ""
    }
    
    class Cancelled(
        ) : SshException() {
        override val message
            get() = ""
    }
    
    class Timeout(
        ) : SshException() {
        override val message
            get() = ""
    }
    
    class Channel(
        
        val `msg`: kotlin.String
        ) : SshException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Sftp(
        
        val `msg`: kotlin.String
        ) : SshException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Io(
        
        val `msg`: kotlin.String
        ) : SshException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class Disconnected(
        ) : SshException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SshException> {
        override fun lift(error_buf: RustBuffer.ByValue): SshException = FfiConverterTypeSshError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSshError : FfiConverterRustBuffer<SshException> {
    override fun read(buf: ByteBuffer): SshException {
        

        return when(buf.getInt()) {
            1 -> SshException.Connect(
                FfiConverterString.read(buf),
                )
            2 -> SshException.HostKeyRejected()
            3 -> SshException.PassphraseRequired()
            4 -> SshException.BadPassphrase()
            5 -> SshException.InvalidKey(
                FfiConverterString.read(buf),
                )
            6 -> SshException.Auth(
                FfiConverterString.read(buf),
                )
            7 -> SshException.AuthMethodNotAvailable(
                FfiConverterString.read(buf),
                )
            8 -> SshException.AuthCancelled()
            9 -> SshException.Cancelled()
            10 -> SshException.Timeout()
            11 -> SshException.Channel(
                FfiConverterString.read(buf),
                )
            12 -> SshException.Sftp(
                FfiConverterString.read(buf),
                )
            13 -> SshException.Io(
                FfiConverterString.read(buf),
                )
            14 -> SshException.Disconnected()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SshException): ULong {
        return when(value) {
            is SshException.Connect -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is SshException.HostKeyRejected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SshException.PassphraseRequired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SshException.BadPassphrase -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SshException.InvalidKey -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is SshException.Auth -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is SshException.AuthMethodNotAvailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is SshException.AuthCancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SshException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SshException.Timeout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SshException.Channel -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is SshException.Sftp -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is SshException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is SshException.Disconnected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: SshException, buf: ByteBuffer) {
        when(value) {
            is SshException.Connect -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is SshException.HostKeyRejected -> {
                buf.putInt(2)
                Unit
            }
            is SshException.PassphraseRequired -> {
                buf.putInt(3)
                Unit
            }
            is SshException.BadPassphrase -> {
                buf.putInt(4)
                Unit
            }
            is SshException.InvalidKey -> {
                buf.putInt(5)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is SshException.Auth -> {
                buf.putInt(6)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is SshException.AuthMethodNotAvailable -> {
                buf.putInt(7)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is SshException.AuthCancelled -> {
                buf.putInt(8)
                Unit
            }
            is SshException.Cancelled -> {
                buf.putInt(9)
                Unit
            }
            is SshException.Timeout -> {
                buf.putInt(10)
                Unit
            }
            is SshException.Channel -> {
                buf.putInt(11)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is SshException.Sftp -> {
                buf.putInt(12)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is SshException.Io -> {
                buf.putInt(13)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is SshException.Disconnected -> {
                buf.putInt(14)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




